/* Adds metadata and required change rationale while retaining previous draft history. */
const orderAnnotations={
'FN-1':[['Investigation','Assess cytopenia and organ function','Initial assessment'],['Investigation','Identify bloodstream infection without treatment delay','Initial assessment; do not delay antibiotics'],['Investigation','Investigate a documented suspected source','When source findings justify testing'],['Safety review','Verify practical outpatient eligibility','Before disposition'],['Monitoring','Reassess before any discharge decision','Before disposition'],['Follow-up','Ensure follow-up access and return precautions','At disposition']],
'FN-2':[['Disposition','High-risk candidate requires inpatient assessment','Urgent clinical review'],['Investigation','Evaluate cytopenia and organ function','Initial assessment; lactate only when indicated'],['Investigation','Identify bloodstream infection','Initial assessment; do not delay antibiotics'],['Medication review','Select an appropriate IV option after local review','Urgent empirical treatment review'],['Safety review','Avoid allergy and renal mismatch','Before medication authorization'],['Monitoring','Track response and deterioration','Document individualized reassessment plan']],
'FN-3':[['Clinical review','Recorded instability needs current assessment','Immediate review of current condition'],['Escalation','Apply approved local rapid-response criteria','Urgent; follow local policy'],['Investigation','Assess perfusion and organ function','Urgent contextual assessment'],['Consultation','Request appropriate specialist support','Urgent according to clinical assessment'],['Medication review','Avoid a fixed regimen regardless of resistance or organ function','Urgent individualized review'],['Monitoring','Assign reassessment and escalation responsibility','During urgent review']],
'FN-4':[['Clinical review','Clarify suspected line source','During source assessment'],['Investigation','Compare peripheral and line culture context','Initial source review; no treatment delay'],['Medication review','Assess whether additional coverage is indicated','After source and clinical review'],['Consultation','Assess line management and source control','Specialist review as indicated']],
'FN-5':[['Clinical review','Verify the actual resistant organism history','Before resistance-specific strategy'],['Safety review','Use exposure and local susceptibility context','During regimen review'],['Consultation','Avoid a universal resistance regimen','Specialist assessment'],['Monitoring','Use new identification and susceptibility evidence','When results become available']],
'FN-6':[['Clinical review','Verify adequate therapy and persistent fever','At persistent-fever reassessment'],['Safety review','Contextualize neutropenia and prior prophylaxis','Before fungal strategy review'],['Investigation','Seek clinically indicated fungal or alternative sources','Specialist-directed review'],['Medication review','Distinguish empirical and pre-emptive strategies','After specialist assessment'],['Monitoring','Document continuing response and deterioration','Individualized reassessment']]
};
function itemMetadata(k,i,p){const a=orderAnnotations[k]?.[i],t=templates[k];if(!a)return {code:k+'-CUSTOM',type:'User-added draft',reason:'User-entered item; source mapping pending',timing:'Not specified',source:'project',sourceLocation:'User draft; validation pending',conditionStatus:'manual'};let eligible=draftPathways(p).matches.some(m=>m.code===k),condition='Candidate '+k+' established by draft mapper';if(k==='FN-1'&&i===2){eligible=eligible&&p['Pneumonia / complex infection']==='Yes';condition='FN-1 candidate AND documented complex/pulmonary infection; other source-specific tests require manual review'}return {code:k+'-ORDER-'+String(i+1).padStart(2,'0'),type:a[0],reason:a[1],timing:a[2]+' · draft workflow',source:t.source,sourceLocation:FNKnowledge.references[t.source].location,ruleIds:[k],condition,conditionStatus:eligible?'met':'not established',approval:'Draft — clinician and pharmacy review pending',knowledgeVersion:FNKnowledge.release}}
generateOrder=function(){const pid=id(selected),k=$('#orderTemplate').value;if(!templates[k]){openDialog('Select a draft template','<p>Select a template deliberately after reviewing candidate modules.</p><button class="btn" onclick="closeDialog()">Back</button>');return}const prev=state.orderDrafts[pid];if(prev)state.orderHistory.unshift({patientId:pid,...JSON.parse(JSON.stringify(prev))});state.orderDrafts[pid]={subtype:k,version:(prev?.version||0)+1,createdAt:new Date().toISOString(),context:orderContext(pid),knowledgeVersion:FNKnowledge.release,items:templates[k].items.map((text,i)=>{const metadata=itemMetadata(k,i,selected);return {text,include:metadata.conditionStatus==='met',metadata,changes:[]}}),review:null};save('Generated traceable conditional draft '+k+'; '+FNKnowledge.release,pid)};
function openOrderChange(i,include){const o=state.orderDrafts[id(selected)],item=o?.items[i];if(!item)return;render();openDialog('Explain order inclusion change',`<p>${esc(item.text)}</p><p>Requested state: <b>${include?'Included':'Excluded'}</b>. A reason is required. This records a new draft version and invalidates prior review.</p><form onsubmit="event.preventDefault();applyOrderChange(${i},${include},this)"><label class="field">Reason<textarea name="reason" required maxlength="800"></textarea></label><button class="btn primary" type="submit">Save new version</button><button class="btn" type="button" onclick="closeDialog()">Cancel — keep previous state</button></form>`)}
toggleOrderItem=function(i,on){openOrderChange(i,on)};
function applyOrderChange(i,on,form){const reason=String(new FormData(form).get('reason')||'').trim(),old=state.orderDrafts[id(selected)]?.items[i];if(!reason||!old)return;const prior=old.include,o=preserveOrderVersion();o.items[i].include=on;o.items[i].changes??=[];o.items[i].changes.push({type:'inclusion',from:prior,to:on,reason,at:new Date().toISOString()});closeDialog();save('Order '+(on?'included':'excluded')+' with reason: '+reason,id(selected))}
editOrderItem=function(i){const o=state.orderDrafts[id(selected)];if(!o)return;openDialog(i<0?'Add traceable draft item':'Edit draft item',`<form onsubmit="event.preventDefault();saveOrderItem(${i},this)"><label class="field">Proposed item<textarea name="text" required maxlength="600">${esc(i<0?'':o.items[i].text)}</textarea></label><label class="field">Reason for adding or editing<textarea name="reason" required maxlength="800"></textarea></label><label class="field">Source / section or outstanding source gap<input name="sourceNote" required maxlength="400"></label><button class="btn primary" type="submit">Save new version</button><button class="btn" type="button" onclick="closeDialog()">Cancel</button></form>`)};
saveOrderItem=function(i,form){const f=new FormData(form),text=String(f.get('text')||'').trim(),reason=String(f.get('reason')||'').trim(),sourceNote=String(f.get('sourceNote')||'').trim();if(!text||!reason||!sourceNote)return;const old=state.orderDrafts[id(selected)],previous=i<0?null:old.items[i]?.text;if(i>=0&&previous===undefined)return;const o=preserveOrderVersion(),change={type:i<0?'added':'edited',from:previous,to:text,reason,sourceNote,at:new Date().toISOString()};if(i<0)o.items.push({text,include:true,metadata:{...itemMetadata(o.subtype,-1,selected),sourceLocation:sourceNote},changes:[change]});else{o.items[i].text=text;o.items[i].changes??=[];o.items[i].changes.push(change);o.items[i].metadata={...(o.items[i].metadata||{}),editedSourceNote:sourceNote,approval:'Modified user draft — revalidation required'}}closeDialog();save('Changed order draft with rationale: '+reason,id(selected))};
const viewBeforeTraceable=orderView;orderView=function(){let h=viewBeforeTraceable(),o=state.orderDrafts[id(selected)];if(!o)return h;for(const item of o.items){const m=item.metadata;const info=m?`<details><summary>${esc(m.type||'Draft')} · Why / timing / source</summary><p>${esc(m.reason)}<br>Timing: ${esc(m.timing)}<br>Condition: ${esc(m.condition||'Manual item')} · ${esc(m.conditionStatus)}<br>Source: ${refLink(m.source||'project')}<br>${esc(m.sourceLocation)}<br>${esc(m.approval||'Draft')} · ${esc(m.knowledgeVersion||'User draft')}</p>${(item.changes||[]).map(c=>`<p>${fmt(c.at)} · ${esc(c.type)} · Reason: ${esc(c.reason)}${c.sourceNote?'<br>Source review: '+esc(c.sourceNote):''}</p>`).join('')}</details>`:'<p class="mini">Legacy draft: source metadata not recorded. Generate a new version to attach current rule metadata.</p>';h=h.replace('<td>'+esc(item.text)+'</td>','<td>'+esc(item.text)+info+'</td>')}return h.replace('<h3>Medication review</h3>','<p>Conditional items remain visible for review; unmet conditions start unchecked. Inclusion or exclusion requires a reason. These are review prompts, not executable orders.</p><h3>Medication review</h3>')};
function proposedOrderCodes(p){return Object.keys(templates).flatMap(k=>templates[k].items.map((_,i)=>itemMetadata(k,i,p)).filter(m=>m.conditionStatus==='met').map(m=>m.code)).sort()}
